#include <bits/stdc++.h>
#include <atcoder/all>

using namespace std;
using namespace atcoder;

int main() {
    int N, Q; cin >> N >> Q;
    vector<pair<int, int>> uv(Q);
    for (int i = 0; i < Q; ++i) {
        int u, v; cin >> u >> v;
        uv[i] = { u - 1, v - 1 };
    }

    //事前準備
    vector<vector<int>> graph(N);
    dsu uf1(N);
    for (int i = 0; i < Q; ++i) {
        auto [u, v] = uv[i];
        if (uf1.same(u, v)) continue;
        uf1.merge(u, v);
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    vector<int> color(N, -1); //0:白, 1:黒
    for (int i = 0; i < N; ++i) {
        if (color[i] != -1) continue;
        color[i] = 0;
        queue<int> q;
        q.push(i);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto& nv : graph[v]) {
                if (color[nv] != -1) continue;
                color[nv] = 1 - color[v];
                q.push(nv);
            }
        }
    }

    //クエリ処理
    dsu uf2(N);
    vector<pair<int, int>> count(N, { 0,0 }); //{白の数, 黒の数}
    for (int i = 0; i < N; ++i) {
        count[i] = (color[i] == 0) ? make_pair(1, 0) : make_pair(0, 1);
    }
    int ans = 0;
    for (int i = 0; i < Q; ++i) {
        auto [u, v] = uv[i];
        if (ans != -1) {
            if (uf2.same(u, v)) {
                if (color[u] == color[v]) ans = -1;
            }
            else {
                auto [uW, uB] = count[uf2.leader(u)];
                auto [vW, vB] = count[uf2.leader(v)];
                ans = ans - min(uW, uB) - min(vW, vB) + min(uW + vW, uB + vB);
                const int nl = uf2.merge(u, v);
                count[nl] = { uW + vW, uB + vB };
            }
        }
        cout << ans << "\n";
    }
}
